import { z } from 'zod';
import type { Detection, NewsItem, PageSignals } from './types';
import type { SellerProfile } from './settings';
import type { HiringSignals } from './hiring';
import { findCompetitors } from './competitors';

/**
 * Structured brief generated by the LLM (step 5).
 * Validated with Zod; the model gets one retry on invalid JSON.
 */

export const TalkingPointSchema = z.object({
  point: z.string().min(1),
  /** Indexes into the news array passed to the prompt. */
  sourceRefs: z.array(z.number().int().nonnegative()),
  /** Indexes into the detections array. Grounds stack-based points. */
  stackRefs: z.array(z.number().int().nonnegative()).default([]),
  /**
   * Grounding basis for this point:
   * - 'news': drawn from a cited headline (sourceRefs)
   * - 'stack': drawn from a detected technology (stackRefs)
   * - 'site': drawn from the company's own website text
   * - 'hiring': drawn from open job postings
   * - 'inference': the model's inference, not directly grounded
   */
  basis: z.enum(['news', 'stack', 'site', 'hiring', 'inference']).default('news'),
});

export const BriefSchema = z.object({
  overview: z.string().min(1),
  /** News indexes cited by the overview. */
  overviewRefs: z.array(z.number().int().nonnegative()).default([]),
  talkingPoints: z.array(TalkingPointSchema).min(1).max(8),
});

export type Brief = z.infer<typeof BriefSchema>;

const ANTHROPIC_URL = 'https://api.anthropic.com/v1/messages';
const ANTHROPIC_VERSION = '2023-06-01';
const MAX_TOKENS = 1024;

export function buildPrompt(
  signals: PageSignals,
  detections: Detection[],
  news: NewsItem[],
  seller: SellerProfile | null,
  hiring: HiringSignals | null = null,
): string {
  const stack = detections
    .map(
      (d, i) =>
        `[S${i}] ${d.name} (${d.category}, ${d.confidence} confidence): ${d.evidence.join('; ')}`,
    )
    .join('\n');

  const headlines = news
    .map(
      (n, i) =>
        `[${i}] "${n.title}" — ${n.source ?? 'unknown'}${n.pubDate ? ` (${n.pubDate.slice(0, 10)})` : ''}`,
    )
    .join('\n');

  const hiringSection = hiring
    ? `HIRING SIGNALS (from the company's public job board, ${hiring.board})
Open roles: ${hiring.totalRoles}
Top departments: ${hiring.departments.map((d) => `${d.name} (${d.count})`).join(', ') || '(unknown)'}
Sample roles:
${hiring.topRoles.map((r) => `- ${r.title}${r.department ? ` (${r.department})` : ''}${r.location ? ` - ${r.location}` : ''}`).join('\n')}

`
    : '';

  const competitorMatches = seller ? findCompetitors(detections, seller.competitors) : [];
  const competitorSection =
    competitorMatches.length > 0
      ? `COMPETITOR ALERT: This prospect already uses ${competitorMatches
          .map((m) => m.detection.name)
          .join(
            ', ',
          )}, which competes with what the seller offers. This is a DISPLACEMENT opportunity: at least one talking point must acknowledge the incumbent and angle on switching (migration ease, gaps in the incumbent, total cost). Do not pitch as if the category were empty.

`
      : '';

  const sellerSection =
    seller && seller.whatYouSell.trim()
      ? `SELLER CONTEXT (the rep using this tool)
What they sell: ${seller.whatYouSell}
Ideal customer: ${seller.idealCustomer || '(not specified)'}
Value props:
${seller.valueProps.map((v, i) => `${i + 1}. ${v}`).join('\n') || '(none listed)'}

`
      : '';

  const talkingPointRule =
    seller && seller.whatYouSell.trim()
      ? `- Every talking point must connect one of the seller's value props to a specific observed signal (tech stack item, headline, or site fact). Lead with the prospect's situation, then the relevant value prop.`
      : `- Every talking point must reference at least one headline by its [index] in sourceRefs.`;

  return `You are writing a one-page sales prospect brief for the company behind this website.

WEBSITE
URL: ${signals.dom.url}
Title: ${signals.dom.title}
Description: ${signals.dom.metaDescription ?? '(none)'}
Visible text (truncated): ${signals.dom.visibleText.slice(0, 1500)}

DETECTED TECH STACK (deterministic, from page signals)
${stack || '(none detected)'}

RECENT NEWS HEADLINES
${headlines || '(none found)'}

${hiringSection}${competitorSection}${sellerSection}RULES
- Only state facts supported by the website text, tech stack, or headlines above. Do NOT invent funding rounds, employee counts, revenue, or partnerships.
- GROUNDING: For each talking point, set "basis" to where the claim comes from: "news" (a headline - include its index in sourceRefs), "stack" (a detected technology - include its [S#] index in stackRefs), "site" (the company's own website text), "hiring" (an open role or hiring pattern from HIRING SIGNALS), or "inference" (your own reasoning, not directly grounded). Never claim a basis you cannot support.
- If a signal is absent (no news, no relevant tech), leave the point out rather than inventing one. Prefer "not found" over guessing.
- The overview may only cite headlines that actually support it; put their indexes in overviewRefs (empty if none apply).
- If the headlines don't support a claim, don't make it.
${talkingPointRule}
- Keep the overview to 3-4 sentences. Keep each talking point to 1-2 sentences.

Respond with ONLY a JSON object matching this shape:
{
  "overview": "string",
  "overviewRefs": [0],
  "talkingPoints": [
    { "point": "string", "sourceRefs": [0, 2], "stackRefs": [], "basis": "news" },
    { "point": "string", "sourceRefs": [], "stackRefs": [0], "basis": "stack" }
  ]
}`;
}

async function callAnthropic(apiKey: string, model: string, prompt: string): Promise<string> {
  const res = await fetch(ANTHROPIC_URL, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-api-key': apiKey,
      'anthropic-version': ANTHROPIC_VERSION,
      'anthropic-dangerous-direct-browser-access': 'true',
    },
    body: JSON.stringify({
      model,
      max_tokens: MAX_TOKENS,
      messages: [{ role: 'user', content: prompt }],
    }),
  });
  if (!res.ok) {
    const body = await res.text().catch(() => '');
    throw new Error(`Anthropic API error: HTTP ${res.status} ${body.slice(0, 200)}`);
  }
  const data = (await res.json()) as {
    content?: Array<{ type?: string; text?: string }>;
  };
  const text = data.content?.find((b) => b.type === 'text')?.text;
  if (!text) throw new Error('Anthropic returned no text content.');
  return text;
}

function parseBrief(raw: string): Brief {
  // Strip markdown code fences if the model wrapped the JSON.
  const cleaned = raw
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();
  return BriefSchema.parse(JSON.parse(cleaned));
}

/**
 * Generate the structured brief. Retries once if the model returns
 * invalid JSON or fails schema validation.
 */
export async function generateBrief(
  apiKey: string,
  model: string,
  signals: PageSignals,
  detections: Detection[],
  news: NewsItem[],
  seller: SellerProfile | null = null,
  hiring: HiringSignals | null = null,
): Promise<Brief> {
  if (!apiKey) throw new Error('No Anthropic API key set. Open the extension options to add one.');
  const prompt = buildPrompt(signals, detections, news, seller, hiring);
  let lastError: unknown;
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const raw = await callAnthropic(apiKey, model, prompt);
      return parseBrief(raw);
    } catch (e) {
      lastError = e;
    }
  }
  throw lastError instanceof Error ? lastError : new Error(String(lastError));
}
